use client;

/**
 * DebtReadout component displays the total debt in a styled section.
 */
const DebtReadout = () => {
  const shown = useCountUp(BLUEPRINT_SEED.totalDebt);

  return (
    <section aria-label="Total debt" className="carbon-face checkered-sweep relative overflow-hidden rounded-lg border border-line p-5">
      <p className="num text-[10px] tracking-[0.2em] text-dim">TOTAL DEBT</p>
      <p className="num mt-1 text-3xl font-bold text-bone">{formatINR(Math.round(shown))}</p>
      <p className="num mt-1 text-[10px] text-dim">principal outstanding</p>
      <motion.div className="mt-4 h-[3px] rounded bg-dim/50"
        initial={{ scaleX: 0 }} animate={{ scaleX: 1 }}
        style={{ transformOrigin: "left" }}
        transition={{ duration: 1.1, ease: [0.16, 1, 0.3, 1] }} />
    </section>
  );
};

export default DebtReadout;
